import csv

series_ids = {
    "CHWPump02": "a39e93e1-f68f-5e9e-b836-56293fd89fa7",
    "Chiller02": "6041ce4e-9251-5a23-9103-a13dcc247d28",
    "SupplyFan_AHU01": "4693f367-6f23-5b26-868f-f17e866f28b6"
}

date_of_interest = "2018-07-19"
sums = {name: 0.0 for name in series_ids}

with open(VALUES_CSV, 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ts_id = row['timeseries_id']
        timestamp = row['timestamp']
        if timestamp.startswith(date_of_interest):
            for name, sid in series_ids.items():
                if ts_id == sid:
                    sums[name] += float(row['value'])

print(sums)
